window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4fd88c3618d9f4c8"]={"versions": [{"id": "FIG-4fd88c3618d9f4c8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Hybrides Architektur- und Konfigurations-Strukturdiagramm (Mapping zwischen AUTOSAR BSW-Konfigurationscontainern und der Laufzeit-Schichtenarchitektur FrTp/FrIf).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Kommunikationsstack (ComStack), Modul <code>FrTp</code> (FlexRay ISO 10681 Transport Layer) direkt oberhalb des <code>FrIf</code> (FlexRay Interface).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des <strong>Full-Duplex-Betriebs</strong> innerhalb einer einzelnen logischen Verbindung. Es demonstriert, wie ein einzelner logischer Kanal (<code>FrtpChannel</code>) über getrennte Tx- und Rx-Pfade gleichzeitiges Senden und Empfangen von Fr N-PDUs für dieselbe <code>FrtpConnection</code> realisiert.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Laufzeit-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>FrTp</code> (FlexRay Transport Layer):</strong> Führt Segmentierung, Reassemblierung, Flusssteuerung (Flow Control) und Verbindungsüberwachung gemäß ISO 10681-2 aus.\n</li><li><strong><code>FrIf</code> (FlexRay Interface):</strong> Abstraktionsschicht zur Hardware-/Treiberansteuerung für PDU-Sende- und Empfangsvorgänge.\n</li><li><strong><code>FrtpChannel</code>:</strong> Logische Laufzeit-Instanz zur Abwicklung von Datentransfers. Unterteilt in zwei parallele, voneinander entkoppelte Halbkanäle:\n<ul class=\"fig-list\"><li><strong><code>Tx</code>-Zweig:</strong> Überträgt segmentierte Nutzdaten nach unten an <code>FrIf</code> und nimmt Flusskontrollnachrichten von <code>FrIf</code> entgegen.\n</li><li><strong><code>Rx</code>-Zweig:</strong> Empfängt segmentierte Nutzdaten von <code>FrIf</code> und sendet Flusskontrollnachrichten an <code>FrIf</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurations-Container (ECUC-Modell) &amp; Referenzen</h5>\n<ul class=\"fig-list\"><li><strong><code>FrtpConnection</code>:</strong> Zentraler Verbindungsparameter-Container. Definiert Adressierungsmodus, Quell-/Ziel-N-PDUs und Laufzeit-Parameter.\n<ul class=\"fig-list\"><li>Im Full-Duplex-Szenario referenzieren <strong>sowohl</strong> <code>FrtpTxConRef</code> <strong>als auch</strong> <code>FrtpRxConRef</code> desselben <code>FrtpChannel</code> identisch auf dieselbe <code>FrtpConnection</code> (1:1-Dual-Mapping).\n</li></ul>\n</li><li><strong><code>FrtpConnectionControl</code>:</strong> Sub-Container von <code>FrtpConnection</code> zur Konfiguration von Flusssteuerungs- und Timing-Attributen (z. B. Timeouts As, Ar, Bs, Cr, Bandbreitenkontrolle / Separation Time STmin).\n</li><li><strong><code>FrtpTxPduPool</code>:</strong> Container zur Zuweisung eines Pools von konfigurierbaren Sende-PDUs (<code>FrIfTxPdu</code>), die für die asynchrone Übertragung reserviert werden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Datenfluss</h4>\n<p class=\"fig-p\">Der Datenaustausch erfolgt über bidirektionale PDU-Typen zwischen <code>FrTp</code> und <code>FrIf</code> ohne gegenseitiges Blockieren (echtes Full Duplex):</p>\n<pre class=\"fig-pre\"><code>        FrTp-Layer                      FrIf-Layer\n  +--------------------+          +--------------------+\n  | Tx: Outgoing Data  | =======&gt; | SF, CF, LF         |\n  | Tx: Incoming Flow  | &lt;======= | FC                 |\n  |                    |          |                    |\n  | Rx: Incoming Data  | &lt;======= | SF, CF, LF         |\n  | Rx: Outgoing Flow  | =======&gt; | FC                 |\n  +--------------------+          +--------------------+</code></pre>\n<h5 class=\"fig-section-h5\">Protokollierte PDU-Typen</h5>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-PDUs (Data Frames):</strong>\n<ul class=\"fig-list\"><li><code>SF</code> (Single Frame): Unsegmentierte Botschaften ≤ Nutzlastlimit.\n</li><li><code>CF</code> (Consecutive Frame): Folgesegmente eines segmentierten Transfers.\n</li><li><code>LF</code> (Last Frame): Abschließendes Segment eines Datenstroms.\n</li></ul>\n</li><li><strong>Flusskontroll-PDU (Control Frame):</strong>\n<ul class=\"fig-list\"><li><code>FC</code> (Flow Control Frame): Steuerung von Frame-Quittierung, Buffer-Status (<code>CTS</code>, <code>WT</code>, <code>OVFLW</code>) und Bandbreitenkontrolle.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Parallele Signalisierungsabläufe</h5>\n<ol class=\"fig-list\"><li><strong>Tx-Pfad (Senden großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>PDU Router (<code>PduR</code>) initiiert Transfer via <code>FrTp_Transmit()</code>.\n</li><li><code>FrTp</code> sendet <code>SF</code> bzw. Sequenzen aus <code>CF</code>/<code>LF</code> über <code>FrIf_Transmit()</code>.\n</li><li>Bei segmentierter Übertragung empfängt der Tx-Pfad über <code>FrTp_RxIndication()</code> eingehende <code>FC</code>-PDUs des fernen Empfängers zur Weiterschaltung des Sendefensters.\n</li></ul>\n</li><li><strong>Rx-Pfad (Empfang großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>Eingehende <code>SF</code> oder First-Frames triggern PDU-Pufferallokation über <code>PduR_FrTpStartOfReception()</code>.\n</li><li>Folgesegmente (<code>CF</code>, <code>LF</code>) treffen via <code>FrTp_RxIndication()</code> ein.\n</li><li>Der Rx-Pfad generiert und versendet <code>FC</code>-Frames via <code>FrIf_Transmit()</code> zur Flusskontrolle an den fernen Sender.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Puffer- und Ressourcen-Separation:</strong>\n<ul class=\"fig-list\"><li>Im Full-Duplex-Betrieb müssen die Zustandsmaschinen und Puffer für Tx und Rx strikt getrennt allokiert werden (zwei unabhängige State Machines innerhalb eines Kanals).\n</li><li>Ein blockierender Zustand im Empfangspfad (z. B. Wartezeit auf Puffer via <code>PduR_FrTpCopyRxData</code> mit <code>BUFREQ_E_BUSY</code>) darf den Sendepfad der gleichen <code>FrtpConnection</code> weder anhalten noch verzögern.\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (ECUC):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei gesetztem Full-Duplex-Modus sowohl <code>FrtpTxConRef</code> als auch <code>FrtpRxConRef</code> auf denselben <code>FrtpConnection</code>-Knoten zeigen.\n</li><li>Ein <code>FrtpTxPduPool</code> muss ausreichend PDU-Ressourcen bereitstellen, um gleichzeitiges Senden von Nutzdaten (<code>SF</code>/<code>CF</code>/<code>LF</code> aus Tx) und Empfangs-Flusssteuerungen (<code>FC</code> aus Rx) im selben FlexRay-Kommunikationszyklus abdecken zu können.\n</li></ul>\n</li><li><strong>Deadlock- und Race-Condition-Prävention:</strong>\n<ul class=\"fig-list\"><li>Reentrancy-Anforderung: <code>FrTp_RxIndication()</code> und <code>FrTp_TxConfirmation()</code> können verschachtelt oder aus unterschiedlichen FlexRay-Tasks/Interrupts aufgerufen werden. Die Kanalverwaltung muss synchronisationssicher (Critical Sections) gegen parallele Zugriffe auf Verbindungsdatenstrukturen ausgelegt sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-98ca1e9bd1a55ab5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Hybrides Architektur- und Konfigurations-Strukturdiagramm (Mapping zwischen AUTOSAR BSW-Konfigurationscontainern und der Laufzeit-Schichtenarchitektur FrTp/FrIf).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Kommunikationsstack (ComStack), Modul <code>FrTp</code> (FlexRay ISO 10681 Transport Layer) direkt oberhalb des <code>FrIf</code> (FlexRay Interface).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des <strong>Full-Duplex-Betriebs</strong> innerhalb einer einzelnen logischen Verbindung. Es demonstriert, wie ein einzelner logischer Kanal (<code>FrtpChannel</code>) über getrennte Tx- und Rx-Pfade gleichzeitiges Senden und Empfangen von Fr N-PDUs für dieselbe <code>FrtpConnection</code> realisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Laufzeit-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>FrTp</code> (FlexRay Transport Layer):</strong> Führt Segmentierung, Reassemblierung, Flusssteuerung (Flow Control) und Verbindungsüberwachung gemäß ISO 10681-2 aus.\n</li><li><strong><code>FrIf</code> (FlexRay Interface):</strong> Abstraktionsschicht zur Hardware-/Treiberansteuerung für PDU-Sende- und Empfangsvorgänge.\n</li><li><strong><code>FrtpChannel</code>:</strong> Logische Laufzeit-Instanz zur Abwicklung von Datentransfers. Unterteilt in zwei parallele, voneinander entkoppelte Halbkanäle:\n<ul class=\"fig-list\"><li><strong><code>Tx</code>-Zweig:</strong> Überträgt segmentierte Nutzdaten nach unten an <code>FrIf</code> und nimmt Flusskontrollnachrichten von <code>FrIf</code> entgegen.\n</li><li><strong><code>Rx</code>-Zweig:</strong> Empfängt segmentierte Nutzdaten von <code>FrIf</code> und sendet Flusskontrollnachrichten an <code>FrIf</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurations-Container (ECUC-Modell) &amp; Referenzen</h5>\n<ul class=\"fig-list\"><li><strong><code>FrtpConnection</code>:</strong> Zentraler Verbindungsparameter-Container. Definiert Adressierungsmodus, Quell-/Ziel-N-PDUs und Laufzeit-Parameter.\n<ul class=\"fig-list\"><li>Im Full-Duplex-Szenario referenzieren <strong>sowohl</strong> <code>FrtpTxConRef</code> <strong>als auch</strong> <code>FrtpRxConRef</code> desselben <code>FrtpChannel</code> identisch auf dieselbe <code>FrtpConnection</code> (1:1-Dual-Mapping).\n</li></ul>\n</li><li><strong><code>FrtpConnectionControl</code>:</strong> Sub-Container von <code>FrtpConnection</code> zur Konfiguration von Flusssteuerungs- und Timing-Attributen (z. B. Timeouts As, Ar, Bs, Cr, Bandbreitenkontrolle / Separation Time STmin).\n</li><li><strong><code>FrtpTxPduPool</code>:</strong> Container zur Zuweisung eines Pools von konfigurierbaren Sende-PDUs (<code>FrIfTxPdu</code>), die für die asynchrone Übertragung reserviert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Datenaustausch erfolgt über bidirektionale PDU-Typen zwischen <code>FrTp</code> und <code>FrIf</code> ohne gegenseitiges Blockieren (echtes Full Duplex):</p>\n<pre class=\"fig-pre\"><code>        FrTp-Layer                      FrIf-Layer\n  +--------------------+          +--------------------+\n  | Tx: Outgoing Data  | =======&gt; | SF, CF, LF         |\n  | Tx: Incoming Flow  | &lt;======= | FC                 |\n  |                    |          |                    |\n  | Rx: Incoming Data  | &lt;======= | SF, CF, LF         |\n  | Rx: Outgoing Flow  | =======&gt; | FC                 |\n  +--------------------+          +--------------------+</code></pre>\n<h5 class=\"fig-section-h5\">Protokollierte PDU-Typen</h5>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-PDUs (Data Frames):</strong>\n<ul class=\"fig-list\"><li><code>SF</code> (Single Frame): Unsegmentierte Botschaften ≤ Nutzlastlimit.\n</li><li><code>CF</code> (Consecutive Frame): Folgesegmente eines segmentierten Transfers.\n</li><li><code>LF</code> (Last Frame): Abschließendes Segment eines Datenstroms.\n</li></ul>\n</li><li><strong>Flusskontroll-PDU (Control Frame):</strong>\n<ul class=\"fig-list\"><li><code>FC</code> (Flow Control Frame): Steuerung von Frame-Quittierung, Buffer-Status (<code>CTS</code>, <code>WT</code>, <code>OVFLW</code>) und Bandbreitenkontrolle.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Parallele Signalisierungsabläufe</h5>\n<ol class=\"fig-list\"><li><strong>Tx-Pfad (Senden großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>PDU Router (<code>PduR</code>) initiiert Transfer via <code>FrTp_Transmit()</code>.\n</li><li><code>FrTp</code> sendet <code>SF</code> bzw. Sequenzen aus <code>CF</code>/<code>LF</code> über <code>FrIf_Transmit()</code>.\n</li><li>Bei segmentierter Übertragung empfängt der Tx-Pfad über <code>FrTp_RxIndication()</code> eingehende <code>FC</code>-PDUs des fernen Empfängers zur Weiterschaltung des Sendefensters.\n</li></ul>\n</li><li><strong>Rx-Pfad (Empfang großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>Eingehende <code>SF</code> oder First-Frames triggern PDU-Pufferallokation über <code>PduR_FrTpStartOfReception()</code>.\n</li><li>Folgesegmente (<code>CF</code>, <code>LF</code>) treffen via <code>FrTp_RxIndication()</code> ein.\n</li><li>Der Rx-Pfad generiert und versendet <code>FC</code>-Frames via <code>FrIf_Transmit()</code> zur Flusskontrolle an den fernen Sender.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Puffer- und Ressourcen-Separation:</strong>\n<ul class=\"fig-list\"><li>Im Full-Duplex-Betrieb müssen die Zustandsmaschinen und Puffer für Tx und Rx strikt getrennt allokiert werden (zwei unabhängige State Machines innerhalb eines Kanals).\n</li><li>Ein blockierender Zustand im Empfangspfad (z. B. Wartezeit auf Puffer via <code>PduR_FrTpCopyRxData</code> mit <code>BUFREQ_E_BUSY</code>) darf den Sendepfad der gleichen <code>FrtpConnection</code> weder anhalten noch verzögern.\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (ECUC):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei gesetztem Full-Duplex-Modus sowohl <code>FrtpTxConRef</code> als auch <code>FrtpRxConRef</code> auf denselben <code>FrtpConnection</code>-Knoten zeigen.\n</li><li>Ein <code>FrtpTxPduPool</code> muss ausreichend PDU-Ressourcen bereitstellen, um gleichzeitiges Senden von Nutzdaten (<code>SF</code>/<code>CF</code>/<code>LF</code> aus Tx) und Empfangs-Flusssteuerungen (<code>FC</code> aus Rx) im selben FlexRay-Kommunikationszyklus abdecken zu können.\n</li></ul>\n</li><li><strong>Deadlock- und Race-Condition-Prävention:</strong>\n<ul class=\"fig-list\"><li>Reentrancy-Anforderung: <code>FrTp_RxIndication()</code> und <code>FrTp_TxConfirmation()</code> können verschachtelt oder aus unterschiedlichen FlexRay-Tasks/Interrupts aufgerufen werden. Die Kanalverwaltung muss synchronisationssicher (Critical Sections) gegen parallele Zugriffe auf Verbindungsdatenstrukturen ausgelegt sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-d52797f609cd115c", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Hybrides Architektur- und Konfigurations-Strukturdiagramm (Mapping zwischen AUTOSAR BSW-Konfigurationscontainern und der Laufzeit-Schichtenarchitektur FrTp/FrIf).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Kommunikationsstack (ComStack), Modul <code>FrTp</code> (FlexRay ISO 10681 Transport Layer) direkt oberhalb des <code>FrIf</code> (FlexRay Interface).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des <strong>Full-Duplex-Betriebs</strong> innerhalb einer einzelnen logischen Verbindung. Es demonstriert, wie ein einzelner logischer Kanal (<code>FrtpChannel</code>) über getrennte Tx- und Rx-Pfade gleichzeitiges Senden und Empfangen von Fr N-PDUs für dieselbe <code>FrtpConnection</code> realisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Laufzeit-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>FrTp</code> (FlexRay Transport Layer):</strong> Führt Segmentierung, Reassemblierung, Flusssteuerung (Flow Control) und Verbindungsüberwachung gemäß ISO 10681-2 aus.\n</li><li><strong><code>FrIf</code> (FlexRay Interface):</strong> Abstraktionsschicht zur Hardware-/Treiberansteuerung für PDU-Sende- und Empfangsvorgänge.\n</li><li><strong><code>FrtpChannel</code>:</strong> Logische Laufzeit-Instanz zur Abwicklung von Datentransfers. Unterteilt in zwei parallele, voneinander entkoppelte Halbkanäle:\n<ul class=\"fig-list\"><li><strong><code>Tx</code>-Zweig:</strong> Überträgt segmentierte Nutzdaten nach unten an <code>FrIf</code> und nimmt Flusskontrollnachrichten von <code>FrIf</code> entgegen.\n</li><li><strong><code>Rx</code>-Zweig:</strong> Empfängt segmentierte Nutzdaten von <code>FrIf</code> und sendet Flusskontrollnachrichten an <code>FrIf</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurations-Container (ECUC-Modell) &amp; Referenzen</h5>\n<ul class=\"fig-list\"><li><strong><code>FrtpConnection</code>:</strong> Zentraler Verbindungsparameter-Container. Definiert Adressierungsmodus, Quell-/Ziel-N-PDUs und Laufzeit-Parameter.\n<ul class=\"fig-list\"><li>Im Full-Duplex-Szenario referenzieren <strong>sowohl</strong> <code>FrtpTxConRef</code> <strong>als auch</strong> <code>FrtpRxConRef</code> desselben <code>FrtpChannel</code> identisch auf dieselbe <code>FrtpConnection</code> (1:1-Dual-Mapping).\n</li></ul>\n</li><li><strong><code>FrtpConnectionControl</code>:</strong> Sub-Container von <code>FrtpConnection</code> zur Konfiguration von Flusssteuerungs- und Timing-Attributen (z. B. Timeouts As, Ar, Bs, Cr, Bandbreitenkontrolle / Separation Time STmin).\n</li><li><strong><code>FrtpTxPduPool</code>:</strong> Container zur Zuweisung eines Pools von konfigurierbaren Sende-PDUs (<code>FrIfTxPdu</code>), die für die asynchrone Übertragung reserviert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Datenaustausch erfolgt über bidirektionale PDU-Typen zwischen <code>FrTp</code> und <code>FrIf</code> ohne gegenseitiges Blockieren (echtes Full Duplex):</p>\n<pre class=\"fig-pre\"><code>        FrTp-Layer                      FrIf-Layer\n  +--------------------+          +--------------------+\n  | Tx: Outgoing Data  | =======&gt; | SF, CF, LF         |\n  | Tx: Incoming Flow  | &lt;======= | FC                 |\n  |                    |          |                    |\n  | Rx: Incoming Data  | &lt;======= | SF, CF, LF         |\n  | Rx: Outgoing Flow  | =======&gt; | FC                 |\n  +--------------------+          +--------------------+</code></pre>\n<h5 class=\"fig-section-h5\">Protokollierte PDU-Typen</h5>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-PDUs (Data Frames):</strong>\n<ul class=\"fig-list\"><li><code>SF</code> (Single Frame): Unsegmentierte Botschaften ≤ Nutzlastlimit.\n</li><li><code>CF</code> (Consecutive Frame): Folgesegmente eines segmentierten Transfers.\n</li><li><code>LF</code> (Last Frame): Abschließendes Segment eines Datenstroms.\n</li></ul>\n</li><li><strong>Flusskontroll-PDU (Control Frame):</strong>\n<ul class=\"fig-list\"><li><code>FC</code> (Flow Control Frame): Steuerung von Frame-Quittierung, Buffer-Status (<code>CTS</code>, <code>WT</code>, <code>OVFLW</code>) und Bandbreitenkontrolle.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Parallele Signalisierungsabläufe</h5>\n<ol class=\"fig-list\"><li><strong>Tx-Pfad (Senden großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>PDU Router (<code>PduR</code>) initiiert Transfer via <code>FrTp_Transmit()</code>.\n</li><li><code>FrTp</code> sendet <code>SF</code> bzw. Sequenzen aus <code>CF</code>/<code>LF</code> über <code>FrIf_Transmit()</code>.\n</li><li>Bei segmentierter Übertragung empfängt der Tx-Pfad über <code>FrTp_RxIndication()</code> eingehende <code>FC</code>-PDUs des fernen Empfängers zur Weiterschaltung des Sendefensters.\n</li></ul>\n</li><li><strong>Rx-Pfad (Empfang großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>Eingehende <code>SF</code> oder First-Frames triggern PDU-Pufferallokation über <code>PduR_FrTpStartOfReception()</code>.\n</li><li>Folgesegmente (<code>CF</code>, <code>LF</code>) treffen via <code>FrTp_RxIndication()</code> ein.\n</li><li>Der Rx-Pfad generiert und versendet <code>FC</code>-Frames via <code>FrIf_Transmit()</code> zur Flusskontrolle an den fernen Sender.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Puffer- und Ressourcen-Separation:</strong>\n<ul class=\"fig-list\"><li>Im Full-Duplex-Betrieb müssen die Zustandsmaschinen und Puffer für Tx und Rx strikt getrennt allokiert werden (zwei unabhängige State Machines innerhalb eines Kanals).\n</li><li>Ein blockierender Zustand im Empfangspfad (z. B. Wartezeit auf Puffer via <code>PduR_FrTpCopyRxData</code> mit <code>BUFREQ_E_BUSY</code>) darf den Sendepfad der gleichen <code>FrtpConnection</code> weder anhalten noch verzögern.\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (ECUC):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei gesetztem Full-Duplex-Modus sowohl <code>FrtpTxConRef</code> als auch <code>FrtpRxConRef</code> auf denselben <code>FrtpConnection</code>-Knoten zeigen.\n</li><li>Ein <code>FrtpTxPduPool</code> muss ausreichend PDU-Ressourcen bereitstellen, um gleichzeitiges Senden von Nutzdaten (<code>SF</code>/<code>CF</code>/<code>LF</code> aus Tx) und Empfangs-Flusssteuerungen (<code>FC</code> aus Rx) im selben FlexRay-Kommunikationszyklus abdecken zu können.\n</li></ul>\n</li><li><strong>Deadlock- und Race-Condition-Prävention:</strong>\n<ul class=\"fig-list\"><li>Reentrancy-Anforderung: <code>FrTp_RxIndication()</code> und <code>FrTp_TxConfirmation()</code> können verschachtelt oder aus unterschiedlichen FlexRay-Tasks/Interrupts aufgerufen werden. Die Kanalverwaltung muss synchronisationssicher (Critical Sections) gegen parallele Zugriffe auf Verbindungsdatenstrukturen ausgelegt sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-cf25d8eae59dd445", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Hybrides Architektur- und Konfigurations-Strukturdiagramm (Mapping zwischen AUTOSAR BSW-Konfigurationscontainern und der Laufzeit-Schichtenarchitektur FrTp/FrIf).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Kommunikationsstack (ComStack), Modul <code>FrTp</code> (FlexRay ISO 10681 Transport Layer) direkt oberhalb des <code>FrIf</code> (FlexRay Interface).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des <strong>Full-Duplex-Betriebs</strong> innerhalb einer einzelnen logischen Verbindung. Es demonstriert, wie ein einzelner logischer Kanal (<code>FrtpChannel</code>) über getrennte Tx- und Rx-Pfade gleichzeitiges Senden und Empfangen von Fr N-PDUs für dieselbe <code>FrtpConnection</code> realisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Laufzeit-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>FrTp</code> (FlexRay Transport Layer):</strong> Führt Segmentierung, Reassemblierung, Flusssteuerung (Flow Control) und Verbindungsüberwachung gemäß ISO 10681-2 aus.\n</li><li><strong><code>FrIf</code> (FlexRay Interface):</strong> Abstraktionsschicht zur Hardware-/Treiberansteuerung für PDU-Sende- und Empfangsvorgänge.\n</li><li><strong><code>FrtpChannel</code>:</strong> Logische Laufzeit-Instanz zur Abwicklung von Datentransfers. Unterteilt in zwei parallele, voneinander entkoppelte Halbkanäle:\n<ul class=\"fig-list\"><li><strong><code>Tx</code>-Zweig:</strong> Überträgt segmentierte Nutzdaten nach unten an <code>FrIf</code> und nimmt Flusskontrollnachrichten von <code>FrIf</code> entgegen.\n</li><li><strong><code>Rx</code>-Zweig:</strong> Empfängt segmentierte Nutzdaten von <code>FrIf</code> und sendet Flusskontrollnachrichten an <code>FrIf</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurations-Container (ECUC-Modell) &amp; Referenzen</h5>\n<ul class=\"fig-list\"><li><strong><code>FrtpConnection</code>:</strong> Zentraler Verbindungsparameter-Container. Definiert Adressierungsmodus, Quell-/Ziel-N-PDUs und Laufzeit-Parameter.\n<ul class=\"fig-list\"><li>Im Full-Duplex-Szenario referenzieren <strong>sowohl</strong> <code>FrtpTxConRef</code> <strong>als auch</strong> <code>FrtpRxConRef</code> desselben <code>FrtpChannel</code> identisch auf dieselbe <code>FrtpConnection</code> (1:1-Dual-Mapping).\n</li></ul>\n</li><li><strong><code>FrtpConnectionControl</code>:</strong> Sub-Container von <code>FrtpConnection</code> zur Konfiguration von Flusssteuerungs- und Timing-Attributen (z. B. Timeouts As, Ar, Bs, Cr, Bandbreitenkontrolle / Separation Time STmin).\n</li><li><strong><code>FrtpTxPduPool</code>:</strong> Container zur Zuweisung eines Pools von konfigurierbaren Sende-PDUs (<code>FrIfTxPdu</code>), die für die asynchrone Übertragung reserviert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Datenaustausch erfolgt über bidirektionale PDU-Typen zwischen <code>FrTp</code> und <code>FrIf</code> ohne gegenseitiges Blockieren (echtes Full Duplex):</p>\n<pre class=\"fig-pre\"><code>        FrTp-Layer                      FrIf-Layer\n  +--------------------+          +--------------------+\n  | Tx: Outgoing Data  | =======&gt; | SF, CF, LF         |\n  | Tx: Incoming Flow  | &lt;======= | FC                 |\n  |                    |          |                    |\n  | Rx: Incoming Data  | &lt;======= | SF, CF, LF         |\n  | Rx: Outgoing Flow  | =======&gt; | FC                 |\n  +--------------------+          +--------------------+</code></pre>\n<h5 class=\"fig-section-h5\">Protokollierte PDU-Typen</h5>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-PDUs (Data Frames):</strong>\n<ul class=\"fig-list\"><li><code>SF</code> (Single Frame): Unsegmentierte Botschaften ≤ Nutzlastlimit.\n</li><li><code>CF</code> (Consecutive Frame): Folgesegmente eines segmentierten Transfers.\n</li><li><code>LF</code> (Last Frame): Abschließendes Segment eines Datenstroms.\n</li></ul>\n</li><li><strong>Flusskontroll-PDU (Control Frame):</strong>\n<ul class=\"fig-list\"><li><code>FC</code> (Flow Control Frame): Steuerung von Frame-Quittierung, Buffer-Status (<code>CTS</code>, <code>WT</code>, <code>OVFLW</code>) und Bandbreitenkontrolle.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Parallele Signalisierungsabläufe</h5>\n<ol class=\"fig-list\"><li><strong>Tx-Pfad (Senden großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>PDU Router (<code>PduR</code>) initiiert Transfer via <code>FrTp_Transmit()</code>.\n</li><li><code>FrTp</code> sendet <code>SF</code> bzw. Sequenzen aus <code>CF</code>/<code>LF</code> über <code>FrIf_Transmit()</code>.\n</li><li>Bei segmentierter Übertragung empfängt der Tx-Pfad über <code>FrTp_RxIndication()</code> eingehende <code>FC</code>-PDUs des fernen Empfängers zur Weiterschaltung des Sendefensters.\n</li></ul>\n</li><li><strong>Rx-Pfad (Empfang großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>Eingehende <code>SF</code> oder First-Frames triggern PDU-Pufferallokation über <code>PduR_FrTpStartOfReception()</code>.\n</li><li>Folgesegmente (<code>CF</code>, <code>LF</code>) treffen via <code>FrTp_RxIndication()</code> ein.\n</li><li>Der Rx-Pfad generiert und versendet <code>FC</code>-Frames via <code>FrIf_Transmit()</code> zur Flusskontrolle an den fernen Sender.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Puffer- und Ressourcen-Separation:</strong>\n<ul class=\"fig-list\"><li>Im Full-Duplex-Betrieb müssen die Zustandsmaschinen und Puffer für Tx und Rx strikt getrennt allokiert werden (zwei unabhängige State Machines innerhalb eines Kanals).\n</li><li>Ein blockierender Zustand im Empfangspfad (z. B. Wartezeit auf Puffer via <code>PduR_FrTpCopyRxData</code> mit <code>BUFREQ_E_BUSY</code>) darf den Sendepfad der gleichen <code>FrtpConnection</code> weder anhalten noch verzögern.\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (ECUC):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei gesetztem Full-Duplex-Modus sowohl <code>FrtpTxConRef</code> als auch <code>FrtpRxConRef</code> auf denselben <code>FrtpConnection</code>-Knoten zeigen.\n</li><li>Ein <code>FrtpTxPduPool</code> muss ausreichend PDU-Ressourcen bereitstellen, um gleichzeitiges Senden von Nutzdaten (<code>SF</code>/<code>CF</code>/<code>LF</code> aus Tx) und Empfangs-Flusssteuerungen (<code>FC</code> aus Rx) im selben FlexRay-Kommunikationszyklus abdecken zu können.\n</li></ul>\n</li><li><strong>Deadlock- und Race-Condition-Prävention:</strong>\n<ul class=\"fig-list\"><li>Reentrancy-Anforderung: <code>FrTp_RxIndication()</code> und <code>FrTp_TxConfirmation()</code> können verschachtelt oder aus unterschiedlichen FlexRay-Tasks/Interrupts aufgerufen werden. Die Kanalverwaltung muss synchronisationssicher (Critical Sections) gegen parallele Zugriffe auf Verbindungsdatenstrukturen ausgelegt sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f785879745687161", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Hybrides Architektur- und Konfigurations-Strukturdiagramm (Mapping zwischen AUTOSAR BSW-Konfigurationscontainern und der Laufzeit-Schichtenarchitektur FrTp/FrIf).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Kommunikationsstack (ComStack), Modul <code>FrTp</code> (FlexRay ISO 10681 Transport Layer) direkt oberhalb des <code>FrIf</code> (FlexRay Interface).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des <strong>Full-Duplex-Betriebs</strong> innerhalb einer einzelnen logischen Verbindung. Es demonstriert, wie ein einzelner logischer Kanal (<code>FrtpChannel</code>) über getrennte Tx- und Rx-Pfade gleichzeitiges Senden und Empfangen von Fr N-PDUs für dieselbe <code>FrtpConnection</code> realisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Laufzeit-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>FrTp</code> (FlexRay Transport Layer):</strong> Führt Segmentierung, Reassemblierung, Flusssteuerung (Flow Control) und Verbindungsüberwachung gemäß ISO 10681-2 aus.\n</li><li><strong><code>FrIf</code> (FlexRay Interface):</strong> Abstraktionsschicht zur Hardware-/Treiberansteuerung für PDU-Sende- und Empfangsvorgänge.\n</li><li><strong><code>FrtpChannel</code>:</strong> Logische Laufzeit-Instanz zur Abwicklung von Datentransfers. Unterteilt in zwei parallele, voneinander entkoppelte Halbkanäle:\n<ul class=\"fig-list\"><li><strong><code>Tx</code>-Zweig:</strong> Überträgt segmentierte Nutzdaten nach unten an <code>FrIf</code> und nimmt Flusskontrollnachrichten von <code>FrIf</code> entgegen.\n</li><li><strong><code>Rx</code>-Zweig:</strong> Empfängt segmentierte Nutzdaten von <code>FrIf</code> und sendet Flusskontrollnachrichten an <code>FrIf</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurations-Container (ECUC-Modell) &amp; Referenzen</h5>\n<ul class=\"fig-list\"><li><strong><code>FrtpConnection</code>:</strong> Zentraler Verbindungsparameter-Container. Definiert Adressierungsmodus, Quell-/Ziel-N-PDUs und Laufzeit-Parameter.\n<ul class=\"fig-list\"><li>Im Full-Duplex-Szenario referenzieren <strong>sowohl</strong> <code>FrtpTxConRef</code> <strong>als auch</strong> <code>FrtpRxConRef</code> desselben <code>FrtpChannel</code> identisch auf dieselbe <code>FrtpConnection</code> (1:1-Dual-Mapping).\n</li></ul>\n</li><li><strong><code>FrtpConnectionControl</code>:</strong> Sub-Container von <code>FrtpConnection</code> zur Konfiguration von Flusssteuerungs- und Timing-Attributen (z. B. Timeouts As, Ar, Bs, Cr, Bandbreitenkontrolle / Separation Time STmin).\n</li><li><strong><code>FrtpTxPduPool</code>:</strong> Container zur Zuweisung eines Pools von konfigurierbaren Sende-PDUs (<code>FrIfTxPdu</code>), die für die asynchrone Übertragung reserviert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Datenaustausch erfolgt über bidirektionale PDU-Typen zwischen <code>FrTp</code> und <code>FrIf</code> ohne gegenseitiges Blockieren (echtes Full Duplex):</p>\n<pre class=\"fig-pre\"><code>        FrTp-Layer                      FrIf-Layer\n  +--------------------+          +--------------------+\n  | Tx: Outgoing Data  | =======&gt; | SF, CF, LF         |\n  | Tx: Incoming Flow  | &lt;======= | FC                 |\n  |                    |          |                    |\n  | Rx: Incoming Data  | &lt;======= | SF, CF, LF         |\n  | Rx: Outgoing Flow  | =======&gt; | FC                 |\n  +--------------------+          +--------------------+</code></pre>\n<h5 class=\"fig-section-h5\">Protokollierte PDU-Typen</h5>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-PDUs (Data Frames):</strong>\n<ul class=\"fig-list\"><li><code>SF</code> (Single Frame): Unsegmentierte Botschaften ≤ Nutzlastlimit.\n</li><li><code>CF</code> (Consecutive Frame): Folgesegmente eines segmentierten Transfers.\n</li><li><code>LF</code> (Last Frame): Abschließendes Segment eines Datenstroms.\n</li></ul>\n</li><li><strong>Flusskontroll-PDU (Control Frame):</strong>\n<ul class=\"fig-list\"><li><code>FC</code> (Flow Control Frame): Steuerung von Frame-Quittierung, Buffer-Status (<code>CTS</code>, <code>WT</code>, <code>OVFLW</code>) und Bandbreitenkontrolle.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Parallele Signalisierungsabläufe</h5>\n<ol class=\"fig-list\"><li><strong>Tx-Pfad (Senden großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>PDU Router (<code>PduR</code>) initiiert Transfer via <code>FrTp_Transmit()</code>.\n</li><li><code>FrTp</code> sendet <code>SF</code> bzw. Sequenzen aus <code>CF</code>/<code>LF</code> über <code>FrIf_Transmit()</code>.\n</li><li>Bei segmentierter Übertragung empfängt der Tx-Pfad über <code>FrTp_RxIndication()</code> eingehende <code>FC</code>-PDUs des fernen Empfängers zur Weiterschaltung des Sendefensters.\n</li></ul>\n</li><li><strong>Rx-Pfad (Empfang großer I-PDUs):</strong>\n<ul class=\"fig-list\"><li>Eingehende <code>SF</code> oder First-Frames triggern PDU-Pufferallokation über <code>PduR_FrTpStartOfReception()</code>.\n</li><li>Folgesegmente (<code>CF</code>, <code>LF</code>) treffen via <code>FrTp_RxIndication()</code> ein.\n</li><li>Der Rx-Pfad generiert und versendet <code>FC</code>-Frames via <code>FrIf_Transmit()</code> zur Flusskontrolle an den fernen Sender.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Puffer- und Ressourcen-Separation:</strong>\n<ul class=\"fig-list\"><li>Im Full-Duplex-Betrieb müssen die Zustandsmaschinen und Puffer für Tx und Rx strikt getrennt allokiert werden (zwei unabhängige State Machines innerhalb eines Kanals).\n</li><li>Ein blockierender Zustand im Empfangspfad (z. B. Wartezeit auf Puffer via <code>PduR_FrTpCopyRxData</code> mit <code>BUFREQ_E_BUSY</code>) darf den Sendepfad der gleichen <code>FrtpConnection</code> weder anhalten noch verzögern.\n</li></ul>\n</li><li><strong>Konfigurationsvalidierung (ECUC):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei gesetztem Full-Duplex-Modus sowohl <code>FrtpTxConRef</code> als auch <code>FrtpRxConRef</code> auf denselben <code>FrtpConnection</code>-Knoten zeigen.\n</li><li>Ein <code>FrtpTxPduPool</code> muss ausreichend PDU-Ressourcen bereitstellen, um gleichzeitiges Senden von Nutzdaten (<code>SF</code>/<code>CF</code>/<code>LF</code> aus Tx) und Empfangs-Flusssteuerungen (<code>FC</code> aus Rx) im selben FlexRay-Kommunikationszyklus abdecken zu können.\n</li></ul>\n</li><li><strong>Deadlock- und Race-Condition-Prävention:</strong>\n<ul class=\"fig-list\"><li>Reentrancy-Anforderung: <code>FrTp_RxIndication()</code> und <code>FrTp_TxConfirmation()</code> können verschachtelt oder aus unterschiedlichen FlexRay-Tasks/Interrupts aufgerufen werden. Die Kanalverwaltung muss synchronisationssicher (Critical Sections) gegen parallele Zugriffe auf Verbindungsdatenstrukturen ausgelegt sein.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-4fd88c3618d9f4c8", "to": "FIG-98ca1e9bd1a55ab5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>FrTpRxConRef / Oberer Bildrand:</strong> Verringerung der Bildhöhe von 419 auf 400 Pixel; durch den engeren oberen Bildbeschnitt wird die Beschriftung <code>FrTpRxConRef</code> am oberen Rand angeschnitten.\n</li><li><strong>FrTp:</strong> Geringfügige vertikale Verschiebung der Modulbeschriftung nach oben.\n</li></ul>"}, {"from": "FIG-98ca1e9bd1a55ab5", "to": "FIG-d52797f609cd115c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d52797f609cd115c", "to": "FIG-cf25d8eae59dd445", "fr": "R4.2.2", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>FrTpRxConRef / Oberer Bildrand:</strong> Erweiterung der Bildhöhe von 400 auf 425 Pixel und Vergrößerung des oberen Rands, wodurch die Beschriftung <code>FrTpRxConRef</code> wieder vollständig sichtbar und nicht mehr abgeschnitten ist.\n</li></ul>"}, {"from": "FIG-cf25d8eae59dd445", "to": "FIG-f785879745687161", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
